import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第69章 我没错","description":"","frontmatter":{},"headers":[],"relativePath":"第69章_我没错.md","filePath":"第69章_我没错.md"}'),_={name:"第69章_我没错.md"};function r(u,p,n,s,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第69章-我没错" tabindex="-1">第69章 我没错 <a class="header-anchor" href="#第69章-我没错" aria-label="Permalink to &quot;第69章 我没错&quot;">​</a></h1><p>十一月末有一天，她跟我说了一句话，那句话我后来想了三年。</p><p>她说，我不该跟任何人谈恋爱的。</p><p>那天是我们约好的周六。二十分钟。</p><p>前面十分钟她在讲她们系里的事，讲一个人交作业晚了被挂出来。</p><p>第十一分钟，她忽然说：</p><p>她说，我今天想跟你说一件事。</p><p>我说，你说。</p><p>她说，我这两周什么都没干。</p><p>我说，哪方面。</p><p>她说，哪方面都是。</p><p>她说，我这周的阅读清单一个字没看。</p><p>她说，我这周洗了两次碗，其他全是堆着。</p><p>她说，我昨天从十点坐到两点，坐了一晚上，我什么都没写。</p><p>我说，你是不是不舒服。</p><p>她说，我舒服得很。</p><p>她说，我身体一点事都没有，我精神也很好，我饭吃得比平时多。</p><p>她说，我就是什么都干不下去。</p><p>我说，那可能是累。</p><p>她说，你别给我找原因。</p><p>她说，我告诉你我为什么。</p><p>她说，因为我脑子里一直有事。</p><p>她说，我一直知道今晚十一点我们要说二十分钟。</p><p>她说，我从下午四点开始就在算这个。</p><p>她说，我算了一整个下午。</p><p>她说，我中午吃饭都在算现在离十一点还有几个小时。</p><p>我说，那说明你在意。</p><p>她说，对，我就是在意，所以在意完我今天就这样了。</p><p>我说，那我们把这二十分钟取消。</p><p>她说，你说什么。</p><p>我说，取消，你就不用从下午四点开始算。</p><p>她没回。</p><p>过了大概二十秒，她发了一句。</p><p>她说，你这个人，你解决的都是表面。</p><p>她说，我取消这一次，我下周还是会算。</p><p>她说，而且我还会多一样东西要算，我会想你是不是不想跟我说话才取消的。</p><p>我说，那你到底想我怎么办。</p><p>她说，我没想你怎么办。</p><p>她说，我只是告诉你我的结论。</p><p>我说，什么结论。</p><p>然后她说了那句。</p><p>她说，我不该跟任何人谈恋爱的。</p><p>我坐在那儿等后面半句。</p><p>一般她讲一句狠话，会补一句解释。</p><p>那天她没有。</p><p>我等了三分钟。</p><p>三分钟后她自己往下讲了。</p><p>她说，因为我这个人，我一有那种关系，我就不能干我该干的事。</p><p>她说，我不能干我该干的事，我就开始难受。</p><p>她说，我难受我就会找一个人怪。</p><p>她说，而我怪完以后我又知道对方什么事都没做。</p><p>她说，那我更难受。</p><p>她说，所以我一谈恋爱，最后一定变成我恨一个没做错的人。</p><p>她说，然后我还要负责把这份恨收回去。</p><p>我说，你收得回去吗。</p><p>她说，收不回去。</p><p>她说，收回去也只是下一次再犯。</p><p>我说，那你为什么这次恨不回去。</p><p>她说，谁说我不恨。</p><p>她说，我今天下午四点开始就在恨你。</p><p>她说，我恨你说&quot;那我们把这二十分钟取消&quot;。</p><p>她说，因为你这句话一出来，我就得决定我是接受还是不接受。</p><p>她说，我不想做任何决定。</p><p>她说，我今天连穿什么都想让我妈帮我选。</p><p>我说，对不起。</p><p>她说，你不要对不起。</p><p>我说，那你要什么。</p><p>她说，我要你别把话说到我能接的地方。</p><p>她说，你说&quot;我们取消&quot;，那是给我一个可以接的东西。</p><p>她说，我现在接不了。</p><p>我说，那我怎么说。</p><p>她说，你说&quot;哦&quot;。</p><p>她说，你就说&quot;哦，那你自己看着办&quot;。</p><p>她说，你说完这句你就闭嘴。</p><p>我说，好。</p><p>她说，你别答应，你一答应就像你在配合我。</p><p>她说，我最讨厌被配合。</p><p>我那时候坐在床上，看着屏幕上这些字。</p><p>我承认我心里有一个念头很难听。</p><p>我想的是：那我能怎么办，你说什么都是错。</p><p>我把这个念头压下去。</p><p>我把这个念头压下去的原因是，我认识她六年，我知道她最怕的就是这个念头。</p><p>我回的是：那我没做错什么。</p><p>我打完这句，我就后悔了。</p><p>因为我这句话一出去，就变成我在跟她讲道理。</p><p>而她讲的也是道理。</p><p>她隔了很久。</p><p>然后她回了一句。</p><p>她说，对。</p><p>她说，你没做错。</p><p>她说，你从来没做错。</p><p>她说，这就是最麻烦的地方。</p><p>我说，为什么。</p><p>她说，你要是做错一件事，我可以生气，我可以骂你，我可以把这二十分钟用来跟你吵。</p><p>她说，吵完我就能去写作业了。</p><p>她说，因为你错了，我恨你这件事就成立了。</p><p>她说，可是你没错。</p><p>她说，那你让我把这些恨放到哪儿去。</p><p>她说，我只能放到自己身上。</p><p>她说，我放到自己身上，我就是这两周什么都不干的那个人。</p><p>我看完了。</p><p>我一个字都不敢回。</p><p>因为我知道我只要回一句安慰的话，前面那一整段她就白讲了。</p><p>她会觉得她讲深了，讲多了。</p><p>她会开始收。</p><p>于是我什么也没说。</p><p>十一点十九分，她发了一句。</p><p>她说，我今天说太多了。</p><p>我说，没有。</p><p>她说，你别安慰。</p><p>我说，我今天一句话没讲，我在听。</p><p>她说，那你讲一句。</p><p>我说，讲什么。</p><p>她说，随便，你讲一句你今天怎么样。</p><p>我说，我今天把仓库的架子拆了重装了一遍，我妈说我把家里弄得好乱。</p><p>她说，然后呢。</p><p>我说，然后我把最上面那一层拿胶带缠了两道，怕掉下来。</p><p>她说，缠得好。</p><p>我说，嗯。</p><p>她说，你看，你一嗯，我就知道你想把这个话题结束。</p><p>我说，我今天真的没什么可讲的。</p><p>她说，我知道。</p><p>她说，你每天都没什么可讲的，你每天都有事。</p><p>她说，你只是不讲。</p><p>那晚十一点二十，她下线前发了一句。</p><p>她说，我今天那句&quot;我不该跟任何人谈恋爱&quot;，你别记。</p><p>我回：我记了。</p><p>她回：你记哪句。</p><p>我说：我记的是你说这句之前，你先咳了一声。</p><p>她说：那说明什么。</p><p>我说：说明这句你不是今天想的。</p><p>我说：这句你想很久了，想到喉咙都干了才讲出来。</p><p>她没回。</p><p>第二天是周日，她那天不上线。</p><p>周一晚上她上线，第一句是：那个本子你别写了。</p><p>我说：什么本子。</p><p>她说：你每次回我一句很准的话，你回去就要写下来。</p><p>我说：我没写。</p><p>她说：你在写。</p><p>她说，我不知道你怎么弄到的，但是我讲过的话，我下次一开口，你就接在后面。</p><p>我说，那是因为我记得。</p><p>她说，我不要你记得。</p><p>我说，为什么。</p><p>她说，因为你记得，我就会开始检查我自己。</p><p>她说，我这一辈子检查我自己已经检查得够多了。</p><p>那天我没有回她。</p><p>我把本子合上，压在枕头底下。</p><p>那天夜里我想的是另一件事。</p><p>我想的是她那句&quot;你从来没做错&quot;。</p><p>这句话在她嘴里，是一句判词。</p><p>她说的是：我连恨你都找不到地方，所以我只好恨我自己。</p><p>我这辈子第一次明白，&quot;没有错&quot;也可以是别人的一种负担。</p>',152)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
